@import "@fontsource-variable/nunito-sans";

/* Light (faithful): paper-cream page, warm near-white glass (card), soft charcoal text, one
   teal (primary) for markers, a sandy tan band (secondary) that always carries white text. */
:root {
  --background: oklch(0.941 0.015 71);
  --foreground: oklch(0.283 0.003 345);
  --card: oklch(0.989 0.003 68);
  --card-foreground: oklch(0.283 0.003 345);
  --popover: oklch(0.989 0.003 68);
  --popover-foreground: oklch(0.283 0.003 345);
  --primary: oklch(0.553 0.106 227);
  --primary-foreground: oklch(0.99 0.002 68);
  --secondary: oklch(0.687 0.078 70);
  --secondary-foreground: oklch(0.99 0.002 68);
  --muted: oklch(0.9 0.02 72);
  --muted-foreground: oklch(0.5 0.012 60);
  --accent: oklch(0.915 0.018 72);
  --accent-foreground: oklch(0.283 0.003 345);
  --destructive: oklch(0.577 0.2 27);
  --destructive-foreground: oklch(0.99 0.002 68);
  --border: oklch(0.82 0.014 70);
  --input: oklch(0.82 0.014 70);
  --ring: oklch(0.553 0.106 227);
  --highlight: oklch(0.687 0.078 70);
  --highlight-foreground: oklch(0.99 0.002 68);
  --glow: oklch(0.76 0.07 222);
  --chart-1: oklch(0.553 0.106 227);
  --chart-2: oklch(0.687 0.078 70);
  --chart-3: oklch(0.283 0.003 345);
  --chart-4: oklch(0.76 0.07 222);
  --chart-5: oklch(0.502 0.059 70);
  --sidebar: oklch(0.989 0.003 68);
  --sidebar-foreground: oklch(0.283 0.003 345);
  --sidebar-primary: oklch(0.553 0.106 227);
  --sidebar-primary-foreground: oklch(0.99 0.002 68);
  --sidebar-accent: oklch(0.915 0.018 72);
  --sidebar-accent-foreground: oklch(0.283 0.003 345);
  --sidebar-border: oklch(0.82 0.014 70);
  --sidebar-ring: oklch(0.553 0.106 227);

  --typeface-body: "Nunito Sans Variable", "Nunito Sans", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Nunito Sans Variable", "Nunito Sans", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 125rem;
  --page-gutter: 1.5rem;
  --section-y: clamp(5.5rem, 7vw, 7.5rem);
}

/* Dark: a night-plant sibling: warm charcoal page and glass, cream type, the tan band
   deepened to a dark sand, the teal brightened to read on dark. */
.dark {
  --background: oklch(0.205 0.006 65);
  --foreground: oklch(0.93 0.015 71);
  --card: oklch(0.245 0.007 65);
  --card-foreground: oklch(0.93 0.015 71);
  --popover: oklch(0.245 0.007 65);
  --popover-foreground: oklch(0.93 0.015 71);
  --primary: oklch(0.7 0.11 223);
  --primary-foreground: oklch(0.18 0.01 230);
  --secondary: oklch(0.43 0.055 68);
  --secondary-foreground: oklch(0.97 0.008 71);
  --muted: oklch(0.29 0.01 65);
  --muted-foreground: oklch(0.72 0.02 70);
  --accent: oklch(0.31 0.012 65);
  --accent-foreground: oklch(0.93 0.015 71);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(0.18 0.01 65);
  --border: oklch(1 0 0 / 14%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.7 0.11 223);
  --highlight: oklch(0.62 0.075 70);
  --highlight-foreground: oklch(0.18 0.01 65);
  --glow: oklch(0.55 0.08 222);
  --chart-1: oklch(0.7 0.11 223);
  --chart-2: oklch(0.7 0.075 70);
  --chart-3: oklch(0.93 0.015 71);
  --chart-4: oklch(0.55 0.08 222);
  --chart-5: oklch(0.6 0.06 70);
  --sidebar: oklch(0.245 0.007 65);
  --sidebar-foreground: oklch(0.93 0.015 71);
  --sidebar-primary: oklch(0.7 0.11 223);
  --sidebar-primary-foreground: oklch(0.18 0.01 230);
  --sidebar-accent: oklch(0.31 0.012 65);
  --sidebar-accent-foreground: oklch(0.93 0.015 71);
  --sidebar-border: oklch(1 0 0 / 14%);
  --sidebar-ring: oklch(0.7 0.11 223);
}
